window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a5c1cc1c51342fb4"]={"versions": [{"id": "FIG-a5c1cc1c51342fb4", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzendiagramm) aus dem AUTOSAR-Standard <em>Generic Structure Template</em> (TPS_GenericStructureTemplate). Das Diagramm illustriert das Entwurfsmuster zur Abbildung einer gerichteten Relation zwischen zwei Mengenausprägungen (<code>Collection</code>) über ein eigenständiges Relationsobjekt (<code>Collection</code> der Kategorie <code>RELATION</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Instanzen der Metaklasse <code>Collection</code>:</p>\n<ul class=\"fig-list\"><li><code>DefinedView :Collection</code>: Instanzattributwerte <code>autoCollect = refAll</code>, <code>elementRole = PART_OF_SUBSET</code>, <code>category = SET</code>.\n</li><li><code>ExpandedView :Collection</code>: Instanzattributwerte <code>autoCollect = refNone</code>, <code>elementRole = PART_OF_SUBSET</code>, <code>category = SET</code>.\n</li><li><code>ViewRelation :Collection</code>: Instanzattributwerte <code>category = RELATION</code>, <code>elementRole = AUTO_COLLECTED_FROM</code>.\n</li></ul>\n<p class=\"fig-p\">Gerichtete Assoziationen / Referenzen:</p>\n<ul class=\"fig-list\"><li><code>ViewRelation :Collection</code> referenziert über die gerichtete Assoziationsrolle <code>+element</code> die Instanz <code>DefinedView :Collection</code>.\n</li><li><code>ViewRelation :Collection</code> referenziert über die gerichtete Assoziationsrolle <code>+sourceElement</code> die Instanz <code>ExpandedView :Collection</code>.\n</li><li>Gestrichelte gerichtete Beziehung <code>+autoCollectedFrom</code> von <code>ExpandedView :Collection</code> nach <code>DefinedView :Collection</code>.\n</li><li>Ein UML-Kommentar (Note), verbunden über eine gestrichelte Linie mit der Assoziation <code>+autoCollectedFrom</code> und <code>ViewRelation</code>, beschreibt: „collection represents this relation: ExpandedView is autoCollectedFrom DefinedView.“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel zur semantischen Modellierung von Beziehungen im AUTOSAR-Modell: Eine abgeleitete oder expandierte Menge (<code>ExpandedView</code>) steht über die Relation <code>autoCollectedFrom</code> in Verbindung mit der Ausgangsmenge (<code>DefinedView</code>). Zur Repräsentation dieser semantischen Relation im Metamodell dient die Instanz <code>ViewRelation</code> als Verbindungsknoten, der die Ausgangsmenge als <code>+sourceElement</code> und die Zielmenge als <code>+element</code> referenziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Modellierungsmuster für generische AUTOSAR-Sammlungen (<code>Collection</code>) mit relationaler Semantik. Werkzeuge und Modell-Transformatoren müssen die Attribute <code>category = RELATION</code> und <code>elementRole = AUTO_COLLECTED_FROM</code> in Kombination mit den Rollen <code>+sourceElement</code> und <code>+element</code> interpretieren, um Relationen zwischen Mengen (<code>SET</code>) modellkonform aufzulösen bzw. zu serialisieren.</p>"}, {"id": "FIG-35298ea25f92b9c3", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzendiagramm) aus dem AUTOSAR-Standard <em>Generic Structure Template</em> (TPS_GenericStructureTemplate). Das Diagramm illustriert das Entwurfsmuster zur Abbildung einer gerichteten Relation zwischen zwei Mengenausprägungen (<code>Collection</code>) über ein eigenständiges Relationsobjekt (<code>Collection</code> der Kategorie <code>RELATION</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Instanzen der Metaklasse <code>Collection</code>:</p>\n<ul class=\"fig-list\"><li><code>DefinedView :Collection</code>: Instanzattributwerte <code>autoCollect = refAll</code>, <code>elementRole = PART_OF_SUBSET</code>, <code>category = SET</code>.\n</li><li><code>ExpandedView :Collection</code>: Instanzattributwerte <code>autoCollect = refNone</code>, <code>elementRole = PART_OF_SUBSET</code>, <code>category = SET</code>.\n</li><li><code>ViewRelation :Collection</code>: Instanzattributwerte <code>category = RELATION</code>, <code>elementRole = AUTO_COLLECTED_FROM</code>.\n</li></ul>\n<p class=\"fig-p\">Gerichtete Assoziationen / Referenzen:</p>\n<ul class=\"fig-list\"><li><code>ViewRelation :Collection</code> referenziert über die gerichtete Assoziationsrolle <code>+element</code> die Instanz <code>DefinedView :Collection</code>.\n</li><li><code>ViewRelation :Collection</code> referenziert über die gerichtete Assoziationsrolle <code>+sourceElement</code> die Instanz <code>ExpandedView :Collection</code>.\n</li><li>Gestrichelte gerichtete Beziehung <code>+autoCollectedFrom</code> von <code>ExpandedView :Collection</code> nach <code>DefinedView :Collection</code>.\n</li><li>Ein UML-Kommentar (Note), verbunden über eine gestrichelte Linie mit der Assoziation <code>+autoCollectedFrom</code> und <code>ViewRelation</code>, beschreibt: „collection represents this relation: ExpandedView is autoCollectedFrom DefinedView.“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel zur semantischen Modellierung von Beziehungen im AUTOSAR-Modell: Eine abgeleitete oder expandierte Menge (<code>ExpandedView</code>) steht über die Relation <code>autoCollectedFrom</code> in Verbindung mit der Ausgangsmenge (<code>DefinedView</code>). Zur Repräsentation dieser semantischen Relation im Metamodell dient die Instanz <code>ViewRelation</code> als Verbindungsknoten, der die Ausgangsmenge als <code>+sourceElement</code> und die Zielmenge als <code>+element</code> referenziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Modellierungsmuster für generische AUTOSAR-Sammlungen (<code>Collection</code>) mit relationaler Semantik. Werkzeuge und Modell-Transformatoren müssen die Attribute <code>category = RELATION</code> und <code>elementRole = AUTO_COLLECTED_FROM</code> in Kombination mit den Rollen <code>+sourceElement</code> und <code>+element</code> interpretieren, um Relationen zwischen Mengen (<code>SET</code>) modellkonform aufzulösen bzw. zu serialisieren.</p>"}, {"id": "FIG-973b7de772075783", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzendiagramm) aus dem AUTOSAR-Standard <em>Generic Structure Template</em> (TPS_GenericStructureTemplate). Das Diagramm illustriert das Entwurfsmuster zur Abbildung einer gerichteten Relation zwischen zwei Mengenausprägungen (<code>Collection</code>) über ein eigenständiges Relationsobjekt (<code>Collection</code> der Kategorie <code>RELATION</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Instanzen der Metaklasse <code>Collection</code>:</p>\n<ul class=\"fig-list\"><li><code>DefinedView: Collection</code>: Instanzattributwerte <code>autoCollect = refAll</code>, <code>elementRole = PART_OF_SUBSET</code>, <code>category = SET</code>.\n</li><li><code>ExpandedView: Collection</code>: Instanzattributwerte <code>autoCollect = refNone</code>, <code>elementRole = PART_OF_SUBSET</code>, <code>category = SET</code>.\n</li><li><code>ViewRelation: Collection</code>: Instanzattributwerte <code>category = RELATION</code>, <code>elementRole = AUTO_COLLECTED_FROM</code>.\n</li></ul>\n<p class=\"fig-p\">Gerichtete Assoziationen / Referenzen:</p>\n<ul class=\"fig-list\"><li><code>ViewRelation: Collection</code> referenziert über die gerichtete Assoziationsrolle <code>+element</code> die Instanz <code>DefinedView: Collection</code>.\n</li><li><code>ViewRelation: Collection</code> referenziert über die gerichtete Assoziationsrolle <code>+sourceElement</code> die Instanz <code>ExpandedView: Collection</code>.\n</li><li>Gestrichelte gerichtete Beziehung <code>+autoCollectedFrom</code> von <code>ExpandedView: Collection</code> nach <code>DefinedView: Collection</code>.\n</li><li>Ein UML-Kommentar (Note), verbunden über eine gestrichelte Linie mit der Assoziation <code>+autoCollectedFrom</code> und <code>ViewRelation</code>, beschreibt: „collection represents this relation: ExpandedView is autoCollectedFrom DefinedView.“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel zur semantischen Modellierung von Beziehungen im AUTOSAR-Modell: Eine abgeleitete oder expandierte Menge (<code>ExpandedView</code>) steht über die Relation <code>autoCollectedFrom</code> in Verbindung mit der Ausgangsmenge (<code>DefinedView</code>). Zur Repräsentation dieser semantischen Relation im Metamodell dient die Instanz <code>ViewRelation</code> als Verbindungsknoten, der die Ausgangsmenge als <code>+sourceElement</code> und die Zielmenge als <code>+element</code> referenziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Modellierungsmuster für generische AUTOSAR-Sammlungen (<code>Collection</code>) mit relationaler Semantik. Werkzeuge und Modell-Transformatoren müssen die Attribute <code>category = RELATION</code> und <code>elementRole = AUTO_COLLECTED_FROM</code> in Kombination mit den Rollen <code>+sourceElement</code> und <code>+element</code> interpretieren, um Relationen zwischen Mengen (<code>SET</code>) modellkonform aufzulösen bzw. zu serialisieren.</p>"}], "trans": [{"from": "FIG-a5c1cc1c51342fb4", "to": "FIG-35298ea25f92b9c3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-35298ea25f92b9c3", "to": "FIG-973b7de772075783", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Instanz-Köpfe <code>ViewRelation: Collection</code>, <code>DefinedView: Collection</code> und <code>ExpandedView: Collection</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code> :Collection</code> zu <code>: Collection</code>).\n</li><li>Kommentarfeld und Instanzbeschriftungen: Typografische Anpassung des Schriftbildes bzw. Neu-Rendering.\n</li></ul>"}]};
